mapper.select:
select sm.menu_id, sm.menu_name, sm.parent_id, sm.order_num, sm.path, sm.component, sm.query, sm.route_name, sm.is_frame, sm.is_cache, sm.menu_type, sm.visible, sm.status, COALESCE(sm.perms,'') as perms, sm.icon, sm.create_time, sm.update_time, sm.remark, psm.menu_name as parent_name from sys_menu as sm LEFT JOIN sys_menu as psm ON psm.menu_id = sm.parent_id
AND sm.menu_name like concat('%', #{menuName}, '%')
AND sm.visible = #{visible}
AND sm.status = #{status}
AND sm.parent_id = #{parentId}
order by sm.parent_id, sm.order_num

select distinct m.menu_id, m.parent_id, m.menu_name, m.path, m.component, m.query, m.route_name, m.visible, m.status, COALESCE(m.perms,'') as perms, m.is_frame, m.is_cache, m.menu_type, m.icon, m.order_num, m.create_time, m.remark from sys_menu m left join sys_role_menu rm on m.menu_id = rm.menu_id left join sys_user_role ur on rm.role_id = ur.role_id left join sys_role ro on ur.role_id = ro.role_id where ur.user_id = #{params.userId}
AND m.menu_name like concat('%', #{menuName}, '%')
AND m.visible = #{visible}
AND m.status = #{status}
order by m.parent_id, m.order_num

select m.menu_id from sys_menu m left join sys_role_menu rm on m.menu_id = rm.menu_id where rm.role_id = #{roleId}
and m.menu_id not in (select m.parent_id from sys_menu m inner join sys_role_menu rm on m.menu_id = rm.menu_id and rm.role_id = #{roleId})
order by m.parent_id, m.order_num
